<style scoped>
.logo {
  position: relative;
  aspect-ratio: 1453 / 308;
  color: var(--cream);
}

.logo-piece {
  position: absolute;
  overflow: visible;
  fill: currentColor;
}

.logo-piece.is-leaf,
.logo-piece.is-tech {
  fill: var(--leaf);
}

.leaf-shade {
  fill: var(--leaf-dark);
}

/* leaves hinge at the stem */
.logo-piece.is-leaf {
  transform-origin: 0% 52%;
}
</style>
